public class AppDb(DbContextOptions<AppDb> options):IdentityDbContext<User>(options) {
 public DbSet<Person> People=>Set<Person>(); public DbSet<WorkAction> Actions=>Set<WorkAction>(); public DbSet<Evidence> Evidence=>Set<Evidence>(); public DbSet<ChangeLog> Changes=>Set<ChangeLog>(); public DbSet<Subtask> Subtasks=>Set<Subtask>();
 public DbSet<Meeting> Meetings=>Set<Meeting>(); public DbSet<Decision> Decisions=>Set<Decision>(); public DbSet<Comment> Comments=>Set<Comment>(); public DbSet<Kpi> Kpis=>Set<Kpi>(); public DbSet<Measurement> Measurements=>Set<Measurement>(); public DbSet<ProcessRecord> Processes=>Set<ProcessRecord>();
 public DbSet<GateCriterion> Gate=>Set<GateCriterion>(); public DbSet<Setting> Settings=>Set<Setting>(); public DbSet<AlertRule> AlertRules=>Set<AlertRule>(); public DbSet<Notification> Notifications=>Set<Notification>(); public DbSet<PrivateNote> PrivateNotes=>Set<PrivateNote>(); public DbSet<MonthlyReport> Reports=>Set<MonthlyReport>(); public DbSet<AdvisorTurn> AdvisorTurns=>Set<AdvisorTurn>();
 protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);if(Database.ProviderName?.Contains("Sqlite")==true){var converter=new Microsoft.EntityFrameworkCore.Storage.ValueConversion.ValueConverter<DateTimeOffset,long>(v=>v.UtcTicks,v=>new DateTimeOffset(v,TimeSpan.Zero));foreach(var entity in b.Model.GetEntityTypes())foreach(var property in entity.GetProperties())if(property.ClrType==typeof(DateTimeOffset)||property.ClrType==typeof(DateTimeOffset?))property.SetValueConverter(converter);}b.Entity<Person>().HasKey(x=>x.Id);b.Entity<Setting>().HasKey(x=>x.Key);b.Entity<WorkAction>().Property(x=>x.Version).IsConcurrencyToken();b.Entity<WorkAction>().HasIndex(x=>x.MandateNumber).IsUnique();b.Entity<User>().HasIndex(x=>x.PersonId).IsUnique();b.Entity<Notification>().HasIndex(x=>new{x.PersonId,x.Key}).IsUnique();b.Entity<MonthlyReport>().HasIndex(x=>x.Month).IsUnique();b.Entity<WorkAction>().HasMany(x=>x.Evidence).WithOne().HasForeignKey(x=>x.ActionId);b.Entity<WorkAction>().HasMany(x=>x.History).WithOne().HasForeignKey(x=>x.ActionId);b.Entity<WorkAction>().HasMany(x=>x.Subtasks).WithOne().HasForeignKey(x=>x.ActionId);b.Entity<GateCriterion>().HasMany(x=>x.Evidence).WithOne().HasForeignKey(x=>x.GateId);b.Entity<Measurement>().HasMany(x=>x.Evidence).WithOne().HasForeignKey(x=>x.MeasurementId);}
}
